pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 d, uint256 w) internal {
        d = bound(d, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(d > 0);
        vm.assume(w <= d);
        vm.assume(address(this).balance >= d);
        try c.deposit{value: d}() {} catch { return; }
        try c.withdraw(w) {} catch { return; }
        bool drainedOk;
        try c.withdraw(d - w) { drainedOk = true; }
        catch { drainedOk = false; }
        bool overReverted;
        try c.withdraw(1) { overReverted = false; }
        catch { overReverted = true; }
        assertTrue(drainedOk && overReverted);
    }

    function testFuzz_run(uint256 d, uint256 w) public {
        _run(d, w);
    }

    receive() external payable {}
}
